// ===== CONFIGURACIÓN =====================================================
// Tus tecnologías: texto que se busca en vendorProject + product (sin distinguir mayúsculas).
// LISTA DE EJEMPLO: top 20 fabricantes por cantidad de KEV en el catálogo (CISA, 2026-10-04). Empates en el corte: se incluyen si son de perímetro o de endpoint.
// No es un inventario real. Reemplázala en n8n por tus tecnologías; no subas la versión real al repo.
const WATCHLIST = ['Microsoft', 'Cisco', 'Apple', 'Adobe', 'Google', 'Oracle', 'Apache', 'Ivanti', 'Fortinet', 'Linux',
  'Citrix', 'D-Link', 'VMware', 'SonicWall', 'Synacor', 'Android', 'Palo Alto Networks', 'Samsung', 'SAP', 'Zyxel', 'Mozilla', 'Atlassian'];
// true = avisar también de KEV nuevas que NO calzan con tu lista (en un bloque aparte).
const NOTIFY_ALL_NEW = true;
// Palabras que identifican equipos de perímetro (heurística).
const EDGE = ['netscaler','gateway','vpn','fortigate','fortios','fortimail','fortiweb','pan-os','globalprotect',
  'asa','firepower','sd-wan','connect secure','sonicwall','big-ip','firewall','router','routeros','junos',
  'check point','zyxel','draytek','esxi','vcenter','exchange','sharepoint'];
// ========================================================================

const kev = $input.first().json;
const vulns = kev.vulnerabilities || [];
const state = $getWorkflowStaticData('global');
const today = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Santiago' }));
today.setHours(12, 0, 0, 0);

// Primera ejecución: guarda la línea base sin alertar (si no, enviaría ~1.700 avisos).
if (!state.seen) {
  state.seen = vulns.map(v => v.cveID);
  state.catalogVersion = kev.catalogVersion;
  state.baselineAt = new Date().toISOString();
  return [];
}
if (state.catalogVersion === kev.catalogVersion) return [];   // sin cambios

const seen = new Set(state.seen);
const fresh = vulns.filter(v => !seen.has(v.cveID));
state.seen = vulns.map(v => v.cveID);
const prevVersion = state.catalogVersion;
state.catalogVersion = kev.catalogVersion;
if (!fresh.length) return [];

const lower = s => String(s || '').toLowerCase();
const terms = WATCHLIST.map(lower);
const enrich = v => {
  const txt = lower(`${v.vendorProject} ${v.product}`);
  const due = new Date(v.dueDate + 'T12:00:00');
  return {
    ...v,
    mine: terms.some(t => txt.includes(t)),
    edge: EDGE.some(e => txt.includes(e)),
    ransomware: v.knownRansomwareCampaignUse === 'Known',
    daysLeft: Math.round((due - today) / 864e5),
  };
};
const items = fresh.map(enrich).sort((a, b) => (b.mine - a.mine) || a.daysLeft - b.daysLeft);
const mine = items.filter(v => v.mine);
const others = items.filter(v => !v.mine);
if (!mine.length && !NOTIFY_ALL_NEW) return [];

const line = v => {
  const tags = [v.edge ? 'PERÍMETRO' : '', v.ransomware ? 'RANSOMWARE' : '', v.forensicTriage === 'Yes' ? 'TRIAGE FORENSE REQUERIDO' : ''].filter(Boolean).join(', ');
  const plazo = v.daysLeft < 0 ? `vencido hace ${-v.daysLeft} d` : `${v.daysLeft} d`;
  return `• ${v.cveID} — ${v.vendorProject} ${v.product}\n  ${v.vulnerabilityName}\n` +
         `  Agregada ${v.dateAdded} · plazo CISA ${v.dueDate} (${plazo})${tags ? ' · ' + tags : ''}\n` +
         `  Acción CISA: ${String(v.requiredAction || '').split('. ')[0]}.\n` +
         `  ${(String(v.notes || '').match(/https?:\/\/\S+/) || ['https://nvd.nist.gov/vuln/detail/' + v.cveID])[0]}`;
};

const priority = mine.some(v => v.edge || v.daysLeft <= 3) ? 'P0' : mine.length ? 'P1' : 'INFO';
const subject = mine.length
  ? `[${priority}] ${mine.length} KEV nueva(s) en tus tecnologías: ${mine.map(v => v.cveID).join(', ')}`
  : `[INFO] ${others.length} KEV nueva(s) en CISA (ninguna en tus tecnologías)`;

let text = `Catálogo CISA KEV ${prevVersion} → ${kev.catalogVersion} · ${fresh.length} entrada(s) nueva(s)\n\n`;
if (mine.length) text += `EN TUS TECNOLOGÍAS (${mine.length})\n${mine.map(line).join('\n\n')}\n\n`;
if (others.length && NOTIFY_ALL_NEW) text += `OTRAS KEV NUEVAS (${others.length})\n${others.map(line).join('\n\n')}\n\n`;
text += `Fuente: github.com/cisagov/kev-data (repositorio oficial de CISA)`;

return [{ json: { priority, subject, text, mineCount: mine.length, newCount: fresh.length,
                  catalogVersion: kev.catalogVersion, cves: items.map(v => v.cveID) } }];
